static bool legalOperations(const char* a) {
    size_t balance = 0;
    for (; *a; ++a) {
        if (*a == 'I') ++balance;
        else if (*a == 'O') {
            if (!balance) return false;
            --balance;
        } else return false;
    }
    return balance == 0;
}
```

